@register(dispatch_mode=Dispatch.DP_COMPUTE_PROTO)
def compute_dt_token_advantages(self, data: DataProto):
    """Attribute prepared response rows using native DP dispatch/collection."""
    from deltatrace_rollout import DeltaTraceRolloutProducer

    if self._is_offload_param:
        load_fsdp_model_to_gpu(self.actor_module_fsdp)
    try:
        if not hasattr(self, "_deltatrace_producer"):
            self._deltatrace_producer = DeltaTraceRolloutProducer(
                self.actor_module_fsdp,
                eos_token_id=data.meta_info['eos_token_id'],
                pad_token_id=data.meta_info['pad_token_id'],
                invalid_action_penalty_coef=(self.config.actor.invalid_action_penalty_coef
                    if self.config.actor.get("use_invalid_action_penalty", True) else 0.0),
            )
        return self._deltatrace_producer.attribute_prepared_batch(data)
    finally:
        if self._is_offload_param:
            offload_fsdp_model_to_cpu(self.actor_module_fsdp)

def trajectory_credit(data, response_data, worker_group, *, eos_token_id, pad_token_id):
    from verl import DataProto
    from dt_training_batch import CREDIT_KEYS, compute_training_credit

    result = {key: torch.zeros_like(data.batch['responses'], dtype=torch.float32) for key in CREDIT_KEYS}
    if response_data is None:
        # Native reset failures can return no actions at all.
        assert not any(data.non_tensor_batch['dt_response_slices'])
        return DataProto.from_dict(tensors=result)
    # Native trajectory truncation can remove a later reward-bearing action
    # from the training tensor. Its real reward remains in response_data; only
    # actions with retained native token slices require a DT request.
    indices = torch.tensor(sorted({source
        for slices in data.non_tensor_batch['dt_response_slices']
        for source, _, length in slices if length > 0}), dtype=torch.long)
    values = compute_training_credit(response_data, worker_group,
        eos_token_id=eos_token_id, pad_token_id=pad_token_id, source_indices=indices)
    for row, slices in enumerate(data.non_tensor_batch['dt_response_slices']):
        for source, start, length in slices:
            for key in CREDIT_KEYS:
                result[key][row, start:start+length] = values.batch[key][source, :length]
    return DataProto.from_dict(tensors=result)

def chunk(self, chunks: int) -> List["DataProto"]:
    """Split the batch among dim=0 into chunks. The meta_info is passed to each DataProto after split.

    Args:
        chunks (int): the number of chunks to split on dim=0

    Returns:
        List[DataProto]: a list of DataProto after splitting
    """
    if not self.is_padding_enabled():
        assert len(self) % chunks == 0, f"only support equal chunk. Got size of DataProto {len(self)} and chunk {chunks}."

    bsz_in_batch = None
    if self.batch is not None:
        batch_lst = self.batch.chunk(chunks=chunks, dim=0)
        bsz_in_batch = np.array([batch.batch_size[0] for batch in batch_lst])
        chunk_indices = np.cumsum(bsz_in_batch)[:-1]
    else:
        batch_lst = [None for _ in range(chunks)]

    non_tensor_batch_lst = [{} for _ in range(chunks)]
    for key, val in self.non_tensor_batch.items():
        assert isinstance(val, np.ndarray)
        if bsz_in_batch is not None:
            non_tensor_lst = np.array_split(val, chunk_indices.tolist())
        else:
            non_tensor_lst = np.array_split(val, chunks)
        assert len(non_tensor_lst) == chunks
        for i in range(chunks):
            non_tensor_batch_lst[i][key] = non_tensor_lst[i]

    output = []
    for i in range(chunks):
        output.append(type(self)(batch=batch_lst[i], non_tensor_batch=non_tensor_batch_lst[i], meta_info=self.meta_info))

    return output

def _split_args_kwargs_data_proto_with_auto_padding(chunks, *args, **kwargs):
    from verl.protocol import DataProto, DataProtoFuture

    splitted_args = []
    splitted_kwargs = {}

    data_proto_len = None
    padding_size = None
    for arg in args:
        assert isinstance(arg, (DataProto, DataProtoFuture))
        if isinstance(arg, DataProto) and arg.is_padding_enabled():
            # for padding, we only support DataProto with same length
            if data_proto_len is None:
                data_proto_len = len(arg)
                padding_size = (chunks - (data_proto_len % chunks)) if (data_proto_len % chunks > 0) else 0
                splitted_kwargs[_padding_size_key] = padding_size
            else:
                assert data_proto_len == len(arg), f"expecting all arg share same length of {data_proto_len}, but got {len(arg)}"
                data_proto_len = len(arg)
            arg.padding(padding_size=padding_size)

        splitted_args.append(arg.chunk(chunks=chunks))

    for key, val in kwargs.items():
        assert isinstance(val, (DataProto, DataProtoFuture))
        if isinstance(val, DataProto) and val.is_padding_enabled():
            # for padding, we only support DataProto with same length
            if data_proto_len is None:
                data_proto_len = len(val)
                padding_size = chunks - (data_proto_len % chunks)
                splitted_kwargs[_padding_size_key] = padding_size
            else:
                assert data_proto_len == len(val), f"expecting all arg share same length of {data_proto_len}, but got {len(val)}"
                data_proto_len = len(val)
        splitted_kwargs[key] = val.chunk(chunks=chunks)

    return splitted_args, splitted_kwargs

