def prepare_native_prefix_leases(runner, requests, *, minibatch_size, eos_token_id, boundary_row_storage=False, observe_boundary_rows=None, individual_prefixes=False):
    from qwen35_native_prefix_artifacts import NativePrefixArtifacts, NativePrefixLease
    from verl import DataProto
    from verl.protocol import pad_dataproto_to_divisor

    started = time.perf_counter()
    batches = [requests[i:i+minibatch_size] for i in range(0, len(requests), minibatch_size)]
    # Reuse the owner's original MIN collective on a boundary known to precede
    # every current action. No current action, query or target is captured.
    prefix_lengths = [runner.model.synchronize_prefix_start(
        min(request['start'] for request in batch)//64*64) for batch in batches]
    row_prefix_lengths = None
    if individual_prefixes:
        # Preserve the original all-rank zero/nonzero branch and its call count.
        # A zero common boundary retains the original no-cache consumer.
        row_prefix_lengths = [tuple(r['start']//64*64 for r in batch) if length else None
                              for batch, length in zip(batches, prefix_lengths)]
        carrier_prefix_lengths = [max(lengths) if lengths is not None else 0 for lengths in row_prefix_lengths]
    needed = {}
    if individual_prefixes:
        for batch, lengths in zip(batches, row_prefix_lengths):
            if lengths is not None:
                for request, length in zip(batch, lengths):
                    needed.setdefault(request['traj_uid'], set()).add(length)
    else:
        for batch, length in zip(batches, prefix_lengths):
            if length:
                for request in batch:
                    needed.setdefault(request['traj_uid'], set()).add(length)

    canonical = {}
    for request in requests:
        uid = request['traj_uid']
        if uid in needed and (uid not in canonical or
                             request['prompt'].numel() > canonical[uid].numel()):
            canonical[uid] = request['prompt']
    if individual_prefixes:
        for batch, lengths in zip(batches, row_prefix_lengths):
            if lengths is not None:
                for request, length in zip(batch, lengths):
                    if not torch.equal(request['prompt'][:length], canonical[request['traj_uid']][:length]):
                        raise ValueError('Original histories do not share the requested factual row prefix')
    else:
        for batch, length in zip(batches, prefix_lengths):
            if length:
                for request in batch:
                    if not torch.equal(request['prompt'][:length], canonical[request['traj_uid']][:length]):
                        raise ValueError('Original histories do not share the requested factual prefix')

def attribute_prepared_batch(self, data):
    """Consume native DP rows whose complete returns were prepared globally."""
    from agent_system.multi_turn_rollout.utils import to_list_of_dict
    from verl import DataProto
    rows = to_list_of_dict(data)
    complete_returns = data.batch['dt_complete_return'].cpu().tolist()
    values = self.attribute_episodes([rows], [0.0], complete_returns=[complete_returns])[0]
    return DataProto.from_dict(tensors={name: torch.stack([value[name] for value in values])
        for name in ('dt_token_advantages', 'dt_q_estimates', 'dt_v_estimates')})
